from datetime import datetime, timezone
from typing import Literal
from pydantic import BaseModel, Field

PlatformType = Literal["instagram", "youtube_shorts", "x", "facebook"]
RiskLevel = Literal["low", "medium", "high"]
ContentFormat = Literal["short_video", "thread", "carousel", "article"]
AspectRatio = Literal["9:16", "1:1", "16:9"]

class ContentPiece(BaseModel):
    """Structured work product generated by a worker pipeline."""
    title: str = Field(description="Internal title of the content item")
    hook: str = Field(description="First 3 seconds attention-grabber or opening sentence")
    body_script: str = Field(description="Core script or article body with formatting")
    caption: str = Field(description="Social media caption optimized for engagement")
    hashtags: list[str] = Field(default_factory=list, description="Relevant contextual hashtags without spam")
    visual_brief: str = Field(description="Directions for B-roll, visuals, text overlays, or slides")
    target_platform: PlatformType = Field(default="instagram", description="Primary target channel")
    monetization_hypothesis: str = Field(description="Explicit explanation of how this piece contributes to revenue")
    factual_checks: list[str] = Field(default_factory=list, description="Claims or stats that require verification")
    estimated_risk_level: RiskLevel = Field(default="low", description="Risk assessment: low, medium, or high")
    risks_and_caveats: list[str] = Field(default_factory=list, description="Specific brand, legal, or factual risks")

class QualityCheckResult(BaseModel):
    """Quality and factuality evaluation result."""
    passed: bool = Field(description="Whether the content passes minimum safety and brand standards")
    score: float = Field(ge=0.0, le=1.0, description="Quality score from 0.0 to 1.0")
    feedback: list[str] = Field(default_factory=list, description="Critique and improvement points")
    flags: list[str] = Field(default_factory=list, description="Flags requiring human attention")

# ============================================================================
# MULTI-FORMAT & CREATIVE ASSET SCHEMAS (MILESTONE 4)
# ============================================================================

class TopicOpportunity(BaseModel):
    """Content opportunity identified during research."""
    title: str = Field(description="Headline / concept of the topic")
    hook_angle: str = Field(description="Unique premise or contrarian hook")
    timeliness_factor: str = Field(description="Why this topic matters right now")
    target_audience_segment: str = Field(description="Sub-segment of worker audience most interested")
    estimated_reach_potential: Literal["standard", "high", "viral"] = "high"
    monetization_angle: str = Field(description="Specific monetization mechanism (affiliate, sponsor, product)")

class SlideItem(BaseModel):
    """Single slide in a carousel format."""
    slide_number: int
    headline: str
    body_text: str
    visual_direction: str

class ThreadPost(BaseModel):
    """Single tweet/post in an X/Twitter thread."""
    post_number: int
    text: str = Field(max_length=280)
    suggested_media: str = ""

class CreativeAssetBrief(BaseModel):
    """Visual generation brief for image/video generative models (Midjourney, Flux, Stable Diffusion)."""
    asset_type: Literal["thumbnail", "broll_video", "carousel_slide", "infographic"]
    prompt: str = Field(description="Prompt describing scene, lighting, style, composition")
    negative_prompt: str = Field(default="low quality, blurry, distorted, text watermark")
    aspect_ratio: AspectRatio = "9:16"
    overlay_text: str = Field(default="", description="Text to render on top of image")
    color_palette: list[str] = Field(default_factory=list, description="Hex codes or palette names")

class MultiFormatDeliverable(BaseModel):
    """Comprehensive content package spanning multiple formats."""
    topic: TopicOpportunity
    worker_id: str
    worker_name: str
    short_video: ContentPiece | None = None
    thread_posts: list[ThreadPost] = Field(default_factory=list)
    carousel_slides: list[SlideItem] = Field(default_factory=list)
    creative_assets: list[CreativeAssetBrief] = Field(default_factory=list)
    created_at: datetime = Field(default_factory=lambda: datetime.now(timezone.utc))
